#!/usr/bin/env node
/**
 * Interactive, local-only first-run setup. No Cloudflare API calls, subprocesses,
 * D1 migrations, authentication, deployment or secret uploads.
 *
 * The operator must create their OWN fresh D1 separately, copy its UUID only
 * into their local terminal, and explicitly confirm before any local files
 * are created. All credentials are generated by the existing reviewed setup.
 */
import { createInterface } from "node:readline/promises";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { initialize, validateNames } from "./self-host-setup.mjs";
import { checkNodeVersion, inspectOfflineReadiness } from "./self-host-readiness.mjs";
import { explainDoctorFailure } from "./self-host-doctor.mjs";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const ROOT_DIR = resolve(ROOT);
const HELP = [
  "Workshop Visitor Terminal — guided self-host setup (LOCAL ONLY).",
  "  node scripts/self-host-wizard.mjs",
  "  node scripts/self-host-wizard.mjs --check",
  "  node scripts/self-host-wizard.mjs --help",
  "Run from a terminal in a fresh, separately extracted self-host package.",
  "Start mode requires an interactive TTY and an already-created OWN disposable D1 UUID.",
  "The wizard NEVER runs Wrangler, logs in, deploys, uploads secrets or writes remote D1.",
  "Existing files are never replaced. --check only reads local state."
].join("\n") + "\n";

export function parseWizardArgs(args) {
  if (args.length === 0) return { command: "start" };
  if (args.length === 1 && ["--help", "-h", "help"].includes(args[0])) return { command: "help" };
  if (args.length === 1 && args[0] === "--check") return { command: "check" };
  throw Error("Use the wizard without arguments, --check or --help");
}

export const WIZARD_INTRO = [
  "LOCAL-ONLY SETUP — no Cloudflare resources will be modified.",
  "First, in your OWN terminal/account, separately run:",
  "  npm ci",
  "  npx wrangler login",
  "  npx wrangler whoami",
  "  npx wrangler d1 create YOUR_NEW_DATABASE_NAME",
  "Confirm your OWN Cloudflare account and a NEW disposable D1 in the dashboard.",
  "Do not provide any credentials, API tokens or existing production D1 UUID.",
  "The following values are entered ONLY into your local terminal."
].join("\n");

export const WIZARD_NEXT = [
  "LOCAL CONFIGURATION READY. Nothing was deployed or uploaded.",
  "The ignored wrangler.selfhost.toml, .wvt-admin-token and .wvt-visit-secret",
  "remain on this computer; never share or commit them.",
  "NEXT: node scripts/self-host-doctor.mjs --steps",
  "Then confirm YOUR account-level workers.dev subdomain in Cloudflare and use:",
  "  node scripts/self-host-doctor.mjs --account-subdomain YOUR_ACCOUNT_LABEL --steps",
  "That command PRINTS manual next steps; no remote command runs automatically.",
  "Only the owner should decide whether to run remote D1 migration/deploy/secret put.",
  "Passing this wizard does NOT verify cloud ownership, billing or GitHub image caching."
].join("\n");

/**
 * The only write is initializeLocal, invoked after two distinct, exact
 * confirmations. Dependency functions are injected for deterministic
 * no-network/zero-write tests; the production defaults are local-only.
 */
export async function runGuidedSetup({
  root = ROOT_DIR,
  ask,
  notify = () => {},
  nodeVersion = process.versions.node,
  initializeLocal = initialize,
  readiness = inspectOfflineReadiness
} = {}) {
  checkNodeVersion(nodeVersion);
  if (typeof ask !== "function" || typeof notify !== "function") {
    throw Error("Interactive terminal required for first-run setup");
  }
  notify(WIZARD_INTRO);
  const ownership = await ask("Type OWN to confirm this is YOUR account and a NEW D1 (anything else cancels): ");
  if (ownership !== "OWN") {
    notify("CANCELLED. No configuration or secret files were created.");
    return { status: "CANCELLED" };
  }

  const worker = (await ask("Unique lowercase Worker name (e.g. my-visitor-worker): ")).trim();
  const database = (await ask("Exact NEW D1 database name: ")).trim();
  const databaseId = (await ask("NEW D1 UUID shown by Wrangler (local input only): ")).trim();
  const options = { worker, database, "database-id": databaseId };
  validateNames(options);

  const confirm = await ask(
    "Type CREATE to write THREE NEW local-only, gitignored config/secret files (anything else cancels): "
  );
  if (confirm !== "CREATE") {
    notify("CANCELLED. No configuration or secret files were created.");
    return { status: "CANCELLED" };
  }

  // initializeLocal refuses overwriting even a partial existing setup.
  // If readiness subsequently fails, preserve created files for inspection:
  // do not silently regenerate credentials or erase a user's configuration.
  await initializeLocal(options, { root });
  const report = await readiness({ root, nodeVersion });
  if (report?.local !== "PASS" ||
      report?.releaseGate !== "PENDING_INDEPENDENT_CLOUDFLARE_TEST") {
    throw Error("Unexpected local readiness status");
  }
  notify(WIZARD_NEXT);
  return { status: "LOCAL_READY", localChecks: "PASS" };
}

export async function checkWizard({
  root = ROOT_DIR,
  nodeVersion = process.versions.node,
  readiness = inspectOfflineReadiness
} = {}) {
  const report = await readiness({ root, nodeVersion });
  if (report?.local !== "PASS" ||
      report?.releaseGate !== "PENDING_INDEPENDENT_CLOUDFLARE_TEST") {
    throw Error("Unexpected local readiness status");
  }
  return "PASS: local setup and locked files are ready for MANUAL independent " +
    "deployment only. Remote account, billing, D1 writes and GitHub proxy NOT_TESTED.\n" +
    "NEXT: node scripts/self-host-doctor.mjs --steps\n";
}

async function main() {
  let interfaceHandle;
  try {
    const args = parseWizardArgs(process.argv.slice(2));
    if (args.command === "help") {
      process.stdout.write(HELP);
    } else if (args.command === "check") {
      process.stdout.write(await checkWizard());
    } else {
      if (!process.stdin.isTTY || !process.stdout.isTTY) {
        throw Error("Interactive terminal required for first-run setup");
      }
      interfaceHandle = createInterface({ input: process.stdin, output: process.stdout });
      const result = await runGuidedSetup({
        ask: question => interfaceHandle.question(question),
        notify: message => process.stdout.write(message + "\n")
      });
      if (result.status !== "LOCAL_READY" && result.status !== "CANCELLED") {
        throw Error("Unexpected wizard result");
      }
    }
  } catch (error) {
    // Never include raw exception messages, D1 UUIDs, credentials, local paths or
    // caller-supplied values in output. Diagnose with the existing redacted tool.
    process.stderr.write(explainDoctorFailure(error) + "\n" +
      "Guided setup stopped. No Cloudflare request or deployment was made.\n");
    process.exitCode = 1;
  } finally {
    interfaceHandle?.close();
  }
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  await main();
}
